//go:build windows

package main

import (
	"runtime"
	"syscall"
	"time"
	"unsafe"

	"github.com/lxn/win"
	"golang.org/x/sys/windows"
)

const (
	appName          = "OK Browser"
	mainClassName    = "OKBrowserMainWnd"
	tabHostClassName = "OKBrowserTabHost"
)

// Hotkey commands (generated by the accelerator table).
const (
	cmdBack         = 201
	cmdForward      = 202
	cmdReload       = 203
	cmdHome         = 204
	cmdFocusAddress = 205
	cmdNewWindow    = 206
	cmdCloseTab     = 207
	cmdZoomIn       = 208
	cmdZoomOut      = 209
	cmdZoomReset    = 210
	cmdPrint        = 211
	cmdFullscreen   = 212
	cmdNextTab      = 213
	cmdPrevTab      = 214
	cmdNewTab       = 215
)

// app is the browser window. The entire UI - the Liquid Glass bar with tabs,
// address field and buttons - is rendered inside the web engine as a frosted
// overlay with real backdrop blur; the native side only provides the window
// frame, hotkeys and tab/window management.
type app struct {
	hwnd     win.HWND
	instance win.HINSTANCE
	accel    win.HACCEL

	tabs      []*tab
	activeIdx int

	scale float64 // DPI scale factor (1.0 = 96 DPI)

	maximized          bool // window is maximized (drives the shell's max icon)
	pendingBubbleFocus bool // focus the address bubble after the next bar push

	hostSeq int // child window id sequence

	// lastSpawn throttles popup storms from web pages.
	lastSpawn time.Time

	// Fullscreen (F11) state.
	fullscreen     bool
	savedStyle     int32
	savedPlacement win.WINDOWPLACEMENT
}

var theApp *app

func wndProc(hwnd win.HWND, msg uint32, wp uintptr, lp unsafe.Pointer) uintptr {
	a := theApp
	if a == nil {
		return win.DefWindowProc(hwnd, msg, wp, uintptr(lp))
	}
	switch msg {
	case win.WM_CREATE:
		a.hwnd = hwnd
		return 0

	case win.WM_SIZE:
		if max := wp == 2; max != a.maximized {
			a.maximized = max
			a.pushBarState() // update the max/restore button icon
		}
		a.layout()
		return 0

	case win.WM_GETMINMAXINFO:
		mmi := (*win.MINMAXINFO)(lp)
		mmi.PtMinTrackSize = win.POINT{X: a.scaled(480), Y: a.scaled(320)}
		return 0

	case win.WM_COMMAND:
		// Hotkeys arrive here (all buttons live in the glass bar).
		switch win.HIWORD(uint32(wp)) {
		case 0, 1:
			a.onCommand(int(win.LOWORD(uint32(wp))))
		}
		return 0

	case win.WM_TIMER:
		if wp == 1 {
			win.KillTimer(a.hwnd, 1)
			a.pushBarState()
			if a.pendingBubbleFocus {
				a.pendingBubbleFocus = false
				a.execActive("window.__okBubbleFocus&&window.__okBubbleFocus()")
			}
		}
		return 0

	case win.WM_DPICHANGED:
		a.onDpiChanged(int(win.HIWORD(uint32(wp))), (*win.RECT)(lp))
		return 0

	case win.WM_XBUTTONDOWN:
		// Extra mouse buttons: back / forward.
		switch win.HIWORD(uint32(wp)) {
		case 1:
			a.onCommand(cmdBack)
		case 2:
			a.onCommand(cmdForward)
		}
		return 0

	case win.WM_ERASEBKGND:
		return 1 // the webview covers everything

	case win.WM_DESTROY:
		win.PostQuitMessage(0)
		return 0
	}
	return win.DefWindowProc(hwnd, msg, wp, uintptr(lp))
}

// NewApp creates the main window and the first tab. It returns false when
// the WebView2 runtime is unavailable.
func NewApp(startURL string) (*app, bool) {
	runtime.LockOSThread()

	a := &app{activeIdx: -1}
	a.scale = float64(dpiOf(0)) / 96.0
	theApp = a

	a.instance = win.GetModuleHandle(nil)
	icon := loadAppIcon(a.instance)
	cursor := win.LoadCursor(0, win.MAKEINTRESOURCE(win.IDC_ARROW))

	if !a.registerClass(mainClassName, windows.NewCallback(wndProc), icon, cursor) {
		return nil, false
	}
	if !a.registerClass(tabHostClassName, windows.NewCallback(defTabHostProc), icon, cursor) {
		return nil, false
	}

	cn, _ := syscall.UTF16PtrFromString(mainClassName)
	tn, _ := syscall.UTF16PtrFromString(appName)
	// Frameless: no native title bar - the glass shell bar IS the window
	// bar. Keep the thick frame for edge resizing, Aero Snap and shadow.
	const framelessStyle = win.WS_OVERLAPPEDWINDOW&^win.WS_CAPTION | win.WS_CLIPCHILDREN
	a.hwnd = win.CreateWindowEx(0, cn, tn,
		framelessStyle,
		win.CW_USEDEFAULT, win.CW_USEDEFAULT,
		a.scaled(1180), a.scaled(820),
		0, 0, a.instance, nil)
	if a.hwnd == 0 {
		return nil, false
	}
	if d := dpiOf(a.hwnd); d > 0 && d != int(a.scale*96) {
		a.scale = float64(d) / 96.0
	}

	a.createAccelerators()

	// Show the window immediately so the browser feels instant; the glass
	// bar and page appear a moment later.
	win.ShowWindow(a.hwnd, win.SW_SHOW)
	win.UpdateWindow(a.hwnd)

	// The first tab embeds the engine; if the runtime is missing the
	// constructor already showed the download dialog.
	if a.newTab(startURL, true) == nil {
		return nil, false
	}
	return a, true
}

// registerClass registers a window class for the main window or tab hosts.
func (a *app) registerClass(name string, proc uintptr, icon win.HANDLE, cursor win.HCURSOR) bool {
	cn, err := syscall.UTF16PtrFromString(name)
	if err != nil {
		return false
	}
	wc := win.WNDCLASSEX{
		CbSize:        uint32(unsafe.Sizeof(win.WNDCLASSEX{})),
		LpfnWndProc:   proc,
		HInstance:     a.instance,
		HIcon:         win.HICON(icon),
		HCursor:       cursor,
		LpszClassName: cn,
		HIconSm:       win.HICON(icon),
	}
	return win.RegisterClassEx(&wc) != 0
}

// defTabHostProc lets tab host windows pass messages to DefWindowProc.
func defTabHostProc(hwnd win.HWND, msg uint32, wp uintptr, lp unsafe.Pointer) uintptr {
	return win.DefWindowProc(hwnd, msg, wp, uintptr(lp))
}

// Run is the Win32 message loop; it returns when the window is closed.
func (a *app) Run() {
	var msg win.MSG
	for {
		r := win.GetMessage(&msg, 0, 0, 0)
		if r <= 0 {
			break
		}
		if translateAccelerator(a.hwnd, a.accel, &msg) != 0 {
			continue
		}
		win.TranslateMessage(&msg)
		win.DispatchMessage(&msg)
	}
}

// loadAppIcon loads the icon embedded by goversioninfo (resource ID 32512).
func loadAppIcon(inst win.HINSTANCE) win.HANDLE {
	for _, id := range []uintptr{32512, 2, 1} {
		if h := win.LoadImage(inst, win.MAKEINTRESOURCE(id), win.IMAGE_ICON,
			0, 0, win.LR_DEFAULTSIZE|win.LR_SHARED); h != 0 {
			return h
		}
	}
	return win.LoadImage(0, win.MAKEINTRESOURCE(win.IDI_APPLICATION), win.IMAGE_ICON,
		0, 0, win.LR_DEFAULTSIZE|win.LR_SHARED)
}

func (a *app) createAccelerators() {
	a.accel = createAcceleratorTable([]accel{
		{fVirtKey | fControl, 'L', cmdFocusAddress},
		{fVirtKey | fAlt, 'D', cmdFocusAddress},
		{fVirtKey | fControl, 'T', cmdNewTab},
		{fVirtKey | fControl, 'N', cmdNewWindow},
		{fVirtKey | fControl, 'W', cmdCloseTab},
		{fVirtKey | fControl, 'R', cmdReload},
		{fVirtKey, win.VK_F5, cmdReload},
		{fVirtKey | fAlt, win.VK_LEFT, cmdBack},
		{fVirtKey | fAlt, win.VK_RIGHT, cmdForward},
		{fVirtKey | fAlt, win.VK_HOME, cmdHome},
		{fVirtKey | fControl, win.VK_TAB, cmdNextTab},
		{fVirtKey | fControl | fShift, win.VK_TAB, cmdPrevTab},
		{fVirtKey | fControl, win.VK_OEM_PLUS, cmdZoomIn},
		{fVirtKey | fControl, win.VK_ADD, cmdZoomIn},
		{fVirtKey | fControl, win.VK_OEM_MINUS, cmdZoomOut},
		{fVirtKey | fControl, win.VK_SUBTRACT, cmdZoomOut},
		{fVirtKey | fControl, '0', cmdZoomReset},
		{fVirtKey | fControl, 'P', cmdPrint},
		{fVirtKey, win.VK_F11, cmdFullscreen},
	})
}

// layout sizes every tab host to fill the whole window (the glass bar floats
// above the page inside the web content). Only the active host is shown.
func (a *app) layout() {
	if a.hwnd == 0 {
		return
	}
	var rc win.RECT
	if !win.GetClientRect(a.hwnd, &rc) {
		return
	}
	w, h := rc.Right, rc.Bottom
	if w <= 0 || h <= 0 {
		return
	}
	for i, t := range a.tabs {
		if i == a.activeIdx {
			win.MoveWindow(t.host, 0, 0, w, h, false)
			win.ShowWindow(t.host, win.SW_SHOW)
			if t.chromium != nil {
				t.chromium.Show()
				t.chromium.Resize()
			}
		} else {
			win.ShowWindow(t.host, win.SW_HIDE)
			if t.chromium != nil {
				t.chromium.Hide()
			}
		}
	}
}

// onAccelerator handles hotkeys pressed while a web page has focus (the
// common case now that the whole UI lives inside the page). The engine
// raises this callback for every non-repeat key-down; returning true marks
// the key as handled so the page never sees it.
func (a *app) onAccelerator(vk uint) bool {
	const (
		vkShift   = 0x10
		vkControl = 0x11
		vkMenu    = 0x12 // Alt
	)
	ctrl := keyDown(vkControl)
	shift := keyDown(vkShift)
	alt := keyDown(vkMenu)

	switch {
	case ctrl && !shift && !alt:
		switch vk {
		case 'T':
			a.onCommand(cmdNewTab)
			return true
		case 'W':
			a.onCommand(cmdCloseTab)
			return true
		case 'L':
			a.onCommand(cmdFocusAddress)
			return true
		case 'N':
			a.onCommand(cmdNewWindow)
			return true
		case 'R':
			a.onCommand(cmdReload)
			return true
		case 'P':
			a.onCommand(cmdPrint)
			return true
		case '0':
			a.onCommand(cmdZoomReset)
			return true
		case win.VK_TAB:
			a.onCommand(cmdNextTab)
			return true
		case win.VK_OEM_PLUS, win.VK_ADD:
			a.onCommand(cmdZoomIn)
			return true
		case win.VK_OEM_MINUS, win.VK_SUBTRACT:
			a.onCommand(cmdZoomOut)
			return true
		}

	case ctrl && shift && !alt:
		if vk == win.VK_TAB {
			a.onCommand(cmdPrevTab)
			return true
		}

	case alt && !ctrl:
		switch vk {
		case win.VK_LEFT:
			a.onCommand(cmdBack)
			return true
		case win.VK_RIGHT:
			a.onCommand(cmdForward)
			return true
		case win.VK_HOME:
			a.onCommand(cmdHome)
			return true
		}

	case !ctrl && !shift && !alt:
		switch vk {
		case win.VK_F5:
			a.onCommand(cmdReload)
			return true
		case win.VK_F11:
			a.onCommand(cmdFullscreen)
			return true
		}
	}
	return false
}

// execActive runs JavaScript in the active tab.
func (a *app) execActive(js string) {
	if t := a.active(); t != nil && t.chromium != nil {
		t.chromium.Eval(js)
	}
}

// onCommand handles hotkeys and mouse-button navigation.
func (a *app) onCommand(id int) {
	t := a.active()
	switch id {
	case cmdBack:
		if t != nil && t.chromium != nil && t.chromium.CanGoBack() {
			t.chromium.GoBack()
			a.scheduleBarPush(false)
		}
	case cmdForward:
		if t != nil && t.chromium != nil && t.chromium.CanGoForward() {
			t.chromium.GoForward()
			a.scheduleBarPush(false)
		}
	case cmdReload:
		if t != nil && t.chromium != nil {
			if t.isStart {
				a.showStartPage(t)
			} else {
				t.chromium.Reload()
			}
		}
	case cmdHome:
		if t != nil {
			a.showStartPage(t)
		}
	case cmdFocusAddress:
		a.execActive("window.__okBubbleFocus&&window.__okBubbleFocus()")
	case cmdNewTab:
		a.newTab("", true)
		a.scheduleBarPush(true) // focus the address bubble once ready
	case cmdNewWindow:
		spawnNewWindow("")
	case cmdCloseTab:
		if len(a.tabs) > 0 {
			a.closeTab(a.activeIdx)
		}
	case cmdNextTab:
		if len(a.tabs) > 1 {
			a.switchToTab((a.activeIdx + 1) % len(a.tabs))
		}
	case cmdPrevTab:
		if len(a.tabs) > 1 {
			a.switchToTab((a.activeIdx - 1 + len(a.tabs)) % len(a.tabs))
		}
	case cmdZoomIn:
		a.setZoom(1.25)
	case cmdZoomOut:
		a.setZoom(0.8)
	case cmdZoomReset:
		a.setZoom(0) // sentinel: reset to 1.0
	case cmdPrint:
		if t != nil && t.chromium != nil {
			t.chromium.Eval("window.print()")
		}
	case cmdFullscreen:
		a.toggleFullscreen()
	}
}

// setZoom multiplies the active tab's zoom (0 resets to 100%).
func (a *app) setZoom(mult float64) {
	t := a.active()
	if t == nil {
		return
	}
	if mult == 0 {
		t.zoom = 1.0
	} else {
		t.zoom *= mult
		if t.zoom < 0.25 {
			t.zoom = 0.25
		}
		if t.zoom > 5.0 {
			t.zoom = 5.0
		}
	}
	a.applyZoomTab(t)
}

// onDpiChanged rescales the window.
func (a *app) onDpiChanged(dpi int, suggested *win.RECT) {
	if dpi > 0 {
		a.scale = float64(dpi) / 96.0
	}
	win.SetWindowPos(a.hwnd, 0, suggested.Left, suggested.Top,
		suggested.Right-suggested.Left, suggested.Bottom-suggested.Top,
		win.SWP_NOZORDER|win.SWP_NOACTIVATE)
}

// toggleFullscreen enters or leaves borderless fullscreen (F11).
func (a *app) toggleFullscreen() {
	if !a.fullscreen {
		a.savedStyle = win.GetWindowLong(a.hwnd, win.GWL_STYLE)
		a.savedPlacement.Length = uint32(unsafe.Sizeof(win.WINDOWPLACEMENT{}))
		win.GetWindowPlacement(a.hwnd, &a.savedPlacement)

		var mi win.MONITORINFO
		mi.CbSize = uint32(unsafe.Sizeof(mi))
		mon := win.MonitorFromWindow(a.hwnd, win.MONITOR_DEFAULTTONEAREST)
		if mon != 0 && win.GetMonitorInfo(mon, &mi) {
			win.SetWindowLong(a.hwnd, win.GWL_STYLE,
				a.savedStyle&^(win.WS_CAPTION|win.WS_THICKFRAME))
			win.SetWindowPos(a.hwnd, 0,
				mi.RcMonitor.Left, mi.RcMonitor.Top,
				mi.RcMonitor.Right-mi.RcMonitor.Left,
				mi.RcMonitor.Bottom-mi.RcMonitor.Top,
				win.SWP_NOZORDER|win.SWP_FRAMECHANGED)
			a.fullscreen = true
		}
		return
	}
	win.SetWindowLong(a.hwnd, win.GWL_STYLE, a.savedStyle)
	win.SetWindowPlacement(a.hwnd, &a.savedPlacement)
	var rc win.RECT
	win.GetWindowRect(a.hwnd, &rc)
	win.SetWindowPos(a.hwnd, 0, rc.Left, rc.Top,
		rc.Right-rc.Left, rc.Bottom-rc.Top,
		win.SWP_NOZORDER|win.SWP_FRAMECHANGED)
	a.fullscreen = false
}

// scaled scales a 96-DPI design value to the current DPI.
func (a *app) scaled(v int32) int32 {
	if a.scale == 1 {
		return v
	}
	return int32(float64(v)*a.scale + 0.5)
}

// send sends a window message with plain integer parameters.
func send(hwnd win.HWND, msg uint32, wp, lp uintptr) uintptr {
	return win.SendMessage(hwnd, msg, wp, lp)
}
